DEFAULT_TIMEOUT = 30

def request_timeout(config):
    return int(config.get('timeout', DEFAULT_TIMEOUT))

from src.settings import request_timeout

def test_old_key():
    assert request_timeout({'timeout': '12'}) == 12

def test_default():
    assert request_timeout({}) == 30

